import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';
import Login from './pages/Login';
import Register from './pages/Register';
import ForgotPassword from './pages/ForgotPassword';
import Finbric from './pages/finbric';

function App() {
  return (
    <AuthProvider>
      {/* scaleRoot scales the entire app layout to 75% while compensating width/height so it fills the viewport */}
      <div className="scaleRoot">
        <BrowserRouter>
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            <Route path="/finbric" element={<Finbric />} />
            <Route path="/" element={<Navigate to="/finbric" replace />} />
            <Route path="*" element={<Navigate to="/finbric" replace />} />
          </Routes>
        </BrowserRouter>
      </div>
    </AuthProvider>
  );
}

export default App;
